import{_ as r,c as o,o as e,a0 as a}from"./chunks/framework.C1J0Vcxi.js";const h=JSON.parse('{"title":"第二十九周：rt-async-k3 极简固件替换 rcpu 与 UART 输入乱码排查","description":"","frontmatter":{"title":"第二十九周：rt-async-k3 极简固件替换 rcpu 与 UART 输入乱码排查","date":"2026-06-29"},"headers":[],"relativePath":"周报-Oveln/2026-06-29-周报二十九.md","filePath":"周报-Oveln/2026-06-29-周报二十九.md"}'),c={name:"周报-Oveln/2026-06-29-周报二十九.md"};function d(l,t,s,n,i,p){return e(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="第二十九周工作总结" tabindex="-1">第二十九周工作总结 <a class="header-anchor" href="#第二十九周工作总结" aria-label="Permalink to &quot;第二十九周工作总结&quot;">​</a></h1><h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h2><p>承接上周在 <code>rt-async-k3</code> 项目下用极简 <code>simplehello.elf</code> 验证 RT24 加载链的工作，本周把 rcpu 上的官方 ESOS 固件<strong>整体替换为自写的极简 Rust 固件</strong>（裸 rtos，仅做启动初始化 + UART 输出）。这条固件必须自己完成 <strong>pinctrl + UART 时钟/初始化</strong>（原本由 ESOS 代劳），目前已能在 RT24 上跑起来并输出日志。</p><p>但暴露出一个顽固问题：<strong>rcpu 的 UART 输入（主机 → RT24 方向）字符乱码</strong>。多轮排查后发现，乱码模式随所用 USB 转串口芯片而变、且官方 ESOS 复现同样现象，最终<strong>怀疑是硬件（rcpu RX 引脚/pinctrl）问题</strong>，本周暂以&quot;仅用输出&quot;的方式继续调试。</p><h2 id="_1-用极简-rust-固件替换-rcpu-的-esos" tabindex="-1">1. 用极简 Rust 固件替换 rcpu 的 ESOS <a class="header-anchor" href="#_1-用极简-rust-固件替换-rcpu-的-esos" aria-label="Permalink to &quot;1. 用极简 Rust 固件替换 rcpu 的 ESOS&quot;">​</a></h2><p>工作目录 <code>../rt-async-k3</code>（已建 <code>apps/rt-async-k3-app</code>、<code>modules/chip-k3-rt24</code>、<code>its/k3_rt24_dual.its</code>、<code>scripts/mkimage.sh</code>）。</p><ul><li>把 rcpu 固件从官方 ESOS 换成最简 Rust 裸 rtos：仅做最小启动初始化并通过 UART 输出，不依赖 ESOS 的任何驱动栈。</li><li>打包进 <code>k3_rt24_dual.its</code> 替换原 <code>rcpu*-fw</code> 节点，由 SPL 经 <code>rproc_load</code>/<code>rproc_start</code> 唤醒。</li><li>结果：固件成功在 RT24 上执行并经 R_UART0 输出日志，<strong>加载链与最小启动在真实硬件上跑通</strong>。</li></ul><h2 id="_2-必须手动-pinctrl-uart-初始化" tabindex="-1">2. 必须手动 pinctrl + UART 初始化 <a class="header-anchor" href="#_2-必须手动-pinctrl-uart-初始化" aria-label="Permalink to &quot;2. 必须手动 pinctrl + UART 初始化&quot;">​</a></h2><p>ESOS 启动早期会做 pinctrl 与外设时钟使能，换成自己的固件后这些步骤都得自己实现：</p><ul><li><strong>pinctrl</strong>：配置 R_UART0 对应引脚的复用（TX/RX 功能选择、上下拉等）。</li><li><strong>UART 初始化</strong>：先经 CCU（<code>0xc0881f00</code>）使能 R_UART 时钟，再按 PXA-UART 寄存器布局初始化波特率/数据位，实现 <code>Chip::put_str</code>。</li></ul><p>这一步本周已打通，输出方向（RT24 → 主机）完全正常。</p><h2 id="_3-uart-输入乱码问题-核心卡点" tabindex="-1">3. UART 输入乱码问题（核心卡点） <a class="header-anchor" href="#_3-uart-输入乱码问题-核心卡点" aria-label="Permalink to &quot;3. UART 输入乱码问题（核心卡点）&quot;">​</a></h2><h3 id="现象" tabindex="-1">现象 <a class="header-anchor" href="#现象" aria-label="Permalink to &quot;现象&quot;">​</a></h3><p>RT24 经 R_UART0 的<strong>输出完全正常</strong>，但主机下发的<strong>输入字符被 rcpu 错误接收</strong>。乱码高度规律、且随主机端 USB 转串口芯片变化：</p><table tabindex="0"><thead><tr><th>主机端串口芯片</th><th>输入 <code>abcd</code> 实际回显</th><th>输入 <code>help</code> 回显</th></tr></thead><tbody><tr><td>自制 USB 转串口</td><td><code>ysrf</code></td><td>—</td></tr><tr><td>JLink 虚拟串口 (VCom)</td><td><code>aabbccdd</code></td><td><code>hheellpp</code></td></tr><tr><td>另一块串口硬件</td><td><code>{}}r</code></td><td>—</td></tr></tbody></table><p><code>aabbccdd</code> / <code>hheellpp</code> 是典型的<strong>字符翻倍</strong>——指向 rcpu 侧 RX 采样率/波特与实际不符（每比特被采样两次）；不同发送芯片产生不同错码，则指向 rcpu RX 引脚的信号完整性/驱动强度问题。</p><p>更诡异的是 <strong>回车仍能正常触发命令</strong>：输入 <code>help</code> 虽回显成 <code>hheellpp</code>，按回车后 msh 却能正确执行 <code>help</code>；而换部分串口芯片时连回车都按不下。</p><h3 id="排查结论-疑似硬件问题" tabindex="-1">排查结论：疑似硬件问题 <a class="header-anchor" href="#排查结论-疑似硬件问题" aria-label="Permalink to &quot;排查结论：疑似硬件问题&quot;">​</a></h3><ul><li><strong>官方 ESOS 复现同样乱码</strong>：换回官方固件，rcpu 输入一样错——排除&quot;自写 Rust 固件的软件 bug&quot;。</li><li><strong>UART0（主核 uboot/linux 侧）串口完全正常</strong>：问题隔离在 rcpu 的输入通路。</li><li><strong>换两台电脑、刷好几遍固件，现象一致</strong>：排除主机与瞬时因素。</li><li>输出方向不受影响，<strong>问题集中在 rcpu 的 RX 引脚/pinctrl</strong>——很可能是该引脚的 pinctrl 配置（驱动强度/上下拉）或硬件本身有问题。</li></ul><h3 id="临时决策" tabindex="-1">临时决策 <a class="header-anchor" href="#临时决策" aria-label="Permalink to &quot;临时决策&quot;">​</a></h3><ul><li>rcpu 的<strong>输出方向不受影响</strong>，<strong>暂时放弃串口输入</strong>，调试只走输出——与过往调试方式一致。</li><li>买一个新的 CH340 芯片，待到手再做一轮对照；若多款芯片下乱码依旧，基本可坐实硬件问题。</li></ul>',21)])])}const _=r(c,[["render",d]]);export{h as __pageData,_ as default};
